import { NEW_PLAYER_KEYWORD_SCENARIOS } from "./newPlayerKeywordScenarios.js";

export interface NewPlayerTopic { id: string; title: string; summary: string; paragraphs: string[]; takeaways: string[]; rules?: Array<{ title: string; points: string[] }>; examples?: Array<{ title: string; text: string; cards?: { id: string; name: string; caption?: string; landscape?: boolean }[] }> }
export interface NewPlayerDomain { id: string; name: string; color: string; identity: string; description: string }
export interface NewPlayerKeyword { term: string; explanation: string; example: string }
/** Short table-side definitions. Opening these never changes a lesson. */
export const NEW_PLAYER_TABLE_TERMS = [
  { term: "Draw", aliases: ["draw", "drawing"], explanation: "Take the top card of your main deck and put it in your hand, where you can decide whether to play it later.", example: "You’ve drawn Sentry, so it’s in your hand. To get it into base you’ll still need to play it and pay 2 energy." },
  { term: "Play", aliases: ["play", "playing"], explanation: "When you play a card from your hand or another place that allows it, pay its cost. A unit normally arrives exhausted, and a spell goes on the chain to wait for its effect.", example: "If Sentry is already on the table, taking it from base to a battlefield is a move. Playing it was how you got it onto the table." },
  { term: "Move", aliases: ["move", "moving"], explanation: "For a standard move in your Main phase, turn a ready unit sideways to take it from base to a battlefield or back again. It has to be on the table already.", example: "You paid for Sentry when you played it, so you won’t pay its printed cost again to move it." },
  { term: "Recall", aliases: ["recall", "recalls", "recalled"], explanation: "If an effect recalls a unit or gear, put it back in its controller’s base. It stays in its current state, including damage and exhaustion, unless the effect says otherwise. Recall doesn’t count as a move or put a card in hand.", example: "Recall a sideways Sentry from Monastery and you’ll find it sideways in base." },
  { term: "Pay", aliases: ["pay", "paying", "cost", "costs"], explanation: "Spend what the card or ability asks for. The number needs energy, each domain symbol needs power, and if both are there you’ll need both.", example: "Ahri shows a 3 and a Mind symbol, so have 3 energy and 1 Mind power ready to spend." },
  { term: "Energy", aliases: ["energy", "tap", "tapping"], explanation: "Turn a ready basic rune sideways to make 1 energy, then spend that energy on a number in a cost.", example: "Your two ready runes can make 1 energy each, which is enough for Watchful Sentry." },
  { term: "Power", aliases: ["power", "recycle", "recycling"], explanation: "A domain symbol in a cost asks for matching power. Recycle a basic rune to the bottom of its deck to make power of its domain, even if the rune’s sideways already.", example: "Use a Mind rune for energy first, then recycle the same rune for 1 Mind power." },
  { term: "Ready / exhausted", aliases: ["ready", "readies", "exhausted", "exhaust", "sideways", "upright"], explanation: "An upright card is ready, and a sideways one is exhausted. Some actions ask you to exhaust a ready card, then you wait for a rule or effect to ready it. An exhausted unit can still defend and deal combat damage.", example: "Play Sentry to a battlefield you control and it can defend straight away, even though it normally needs your next Awaken before it can make a standard move." },
  { term: "Might", aliases: ["might", "damage", "combat"], explanation: "Check a unit’s current Might to see how much combat damage it contributes. If its marked damage reaches that Might, it dies. Both sides deal their combat damage together.", example: "If a 3-Might unit fights a 2-Might unit, one deals 3 and the other deals 2 at the same time." },
  { term: "Damage / heal", aliases: ["damage", "heal", "healed", "healing"], explanation: "Keep damage marked beside the unit, because it can still deal its full Might in combat. Healing clears marked damage and leaves the unit’s Might alone, and you can’t heal a unit that’s already dead.", example: "A unit with 4 Might and 2 damage still deals 4 combat damage, and healing away those 2 damage leaves it on 4 Might." },
  { term: "Chain / resolve", aliases: ["chain", "resolve", "resolves", "resolving"], explanation: "Spells and abilities on the chain are still waiting. Once both players pass, carry out the newest one, which is what resolve means. If there’s an older one left, players get a chance to respond again.", example: "They’ve played Discipline on Sentry, but its Might stays the same until the spell resolves." },
  { term: "Pass", aliases: ["pass", "passing", "passes"], explanation: "If you’ve got a chance to act and you’d rather add nothing, pass and let the other player choose. You’re still on the same turn.", example: "Once you both pass, you can resolve the newest waiting effect, or finish the showdown if the chain’s empty." },
  { term: "Priority / focus", aliases: ["priority", "focus", "showdown"], explanation: "Priority is your chance to act or pass. In an open showdown, focus tells you who can start the next play while the chain’s empty. Check you can pay and that the timing fits as well.", example: "Once a spell is waiting and you have priority, you can answer it with a Reaction." },
  { term: "Target", aliases: ["target", "targets", "targeting"], explanation: "When an effect asks you to choose a card or something else it can affect, that choice is its target. Read the restrictions before picking one.", example: "If Rune Prison is about to stun Sentry, choose Rune Prison on the chain as Defy’s target." },
  { term: "Conquer / hold", aliases: ["conquer", "conquest", "hold", "holding", "score", "point", "points"], explanation: "Gain control after a battlefield’s contest finishes and you can conquer. Keep control until the holding check in your Beginning phase and you can hold. Each battlefield can score once per player per turn.", example: "At 7 points holding can give you the win, while conquering the last point also needs you to have scored every battlefield that turn." },
] as const;

export function newPlayerTermsForText(text: string) {
  const words = new Set(text.toLowerCase().split(/[^a-z]+/));
  return NEW_PLAYER_TABLE_TERMS.filter(entry => entry.aliases.some(alias => words.has(alias))).slice(0, 5);
}
