const FOUNDATION_GLOSSARY: NewPlayerKeyword[] = [
  { term: "BO1 / BO3", explanation: "In best of one (BO1), one game decides the match. In best of three (BO3), you need two game wins, and that’s the setup we’ll use here.", example: "Score eight to win the game, then start the next one back on zero. Winning your second game wins the BO3 match." },
  { term: "Domain / identity", explanation: "A domain is a family of cards with a shared symbol. Look at the domains on your legend to find your deck’s identity, the families you can include.", example: "Ahri’s Calm and Mind symbols allow both families in the deck, but the Mind symbol in her cost still needs Mind power even if you’ve got spare Calm." },
  { term: "Channel", explanation: "Take runes from the rune deck and put them on the table. Now you’ve got runes you can use to make resources when you need them.", example: "Channel two ready runes, then when you want to play Sentry you can exhaust each for 1 energy." },
  { term: "Showdown / focus", explanation: "When a battlefield is contested, the showdown gives the players a chance to act before it’s decided. If the chain’s empty, focus tells you who can start a play, and passing gives the other player their chance.", example: "Say Sentry arrives at a contested battlefield. You both have a chance to play permitted cards before damage, and if you both pass on an empty chain the showdown can finish." },
  { term: "Resolve", explanation: "Carry out the instructions of a spell or ability that’s been waiting. By this point you’ve paid for it and players have had their chance to respond.", example: "Once Discipline resolves you change the unit’s Might, so don’t change the number when the spell first goes on the chain." },
  { term: "Target", explanation: "Look for what the effect asks you to choose, then pick a card or other object that fits all its restrictions.", example: "If you want Defy to stop a spell from hitting your unit, select the eligible spell on the chain." },
  { term: "Action", explanation: "Action gives a card or activated ability another time you can use it, during an open showdown. If something’s already on the chain, you’ll need a way to respond to it.", example: "In a combat showdown, once the chain’s empty and you have the right focus and priority, you can play an Action." },
  { term: "Reaction", explanation: "You get all the times you could use an Action, and you can also answer a spell or ability that’s already waiting when you have priority.", example: "Their spell goes on the chain and you respond with Discipline. Once both players pass, yours resolves first." },
  { term: "Hidden", explanation: "At a battlefield you control, pay 1 power of any domain to hide an eligible card. On a later turn you can play it with Reaction timing, ignoring its base cost but following its restrictions. Lose control and the facedown card goes to the trash during cleanup.", example: "Hide Hidden Blade now and you can pick a friendly or enemy unit there on a later turn, provided it’s at that same battlefield." },
  { term: "Assault", explanation: "Add the stated Might to this unit for as long as it’s an attacker.", example: "Daring Poro’s printed 2 Might becomes 3 when it attacks. When it defends it stays on 2." },
  { term: "Tank", explanation: "When you assign combat damage, a unit with Tank has to take damage before friendly units without that protection, following the usual assignment rules.", example: "If it would take 5 damage to kill Sett and the attacker has only 4, all 4 go to Sett and the unit beside him is safe." },
  { term: "Deathknell", explanation: "When this unit dies, its Deathknell ability triggers. The ability still needs to be dealt with even though the unit has gone to the trash.", example: "Watchful Sentry dies, then its controller draws a card when its ability resolves." },
  { term: "Accelerate", explanation: "When you play a unit with Accelerate, you can pay its additional cost to have it enter ready. Check that the unit actually has the keyword before paying this way.", example: "Make that decision while you’re playing the unit. You can’t pay Accelerate later to ready it after something else happens." },
  { term: "Ganking", explanation: "A unit with Ganking can make its standard move straight from one battlefield to the other. You still need a ready unit to exhaust and a time when you can make that move.", example: "In an open Main phase, exhaust your ready unit with Ganking to get from the left battlefield to the right." },
  { term: "Energy", explanation: "Energy pays the numbers in costs, and each ready basic rune can give you 1 when you exhaust it.", example: "Got two ready runes? Exhaust them both and you can pay the 2 energy for Watchful Sentry." },
  { term: "Power", explanation: "Power pays domain symbols and comes from recycling a matching basic rune. Keep it separate from both energy and Might, which is a unit’s fighting strength.", example: "Ahri asks for Mind power, so I’d recycle a Mind rune here. Spare energy or Calm power won’t pay that symbol." },
  { term: "Exhaust / ready", explanation: "Turn a card sideways when you exhaust it. You might hear someone call that tapping. A rune or unit readies when a rule or effect tells it to.", example: "A unit normally arrives exhausted, so you’ll usually wait until your next Awaken to make its first standard move." },
  { term: "Recycle", explanation: "Put the card on the bottom of its own deck. Using a basic rune’s recycle ability gives you matching power, even if it’s sideways. To get energy as well you need to exhaust it first.", example: "Exhaust your ready rune for energy, then select Recycle for power. You keep the energy, but the rune is back in its deck, so you’ll have to channel it again before it can ready on the table." },
  { term: "Mulligan", explanation: "You get one chance before play to change your opening four for free. Set aside zero, one or two, draw that many replacements, then put the originals on the bottom of your main deck. You’ll still have four and you pay no energy or power.", example: "I’d send the spare Ahri back here because my chosen champion stays in her own zone. If you swap two cards, randomise their order on the bottom and leave the rest of the deck as it is." },
  { term: "Hand", explanation: "These are the cards you’re holding, ready to play when you’ve got the right timing and cost. The faces stay private, but either player can ask how many you have.", example: "When you draw Sentry from the top of your main deck it goes into your hand, where it waits until you play it." },
  { term: "Base", explanation: "Your own area on the table for units and gear. You can build up your units here, but to start scoring with one you’ll need to get it to a battlefield.", example: "Play Sentry into base, then once it’s ready move it out to contest a battlefield." },
  { term: "Conquer", explanation: "Once the contest is settled, gain control with your surviving unit to conquer. You can score there if you haven’t already scored that battlefield this turn.", example: "If Sentry is the only unit left there after combat, you can take control of the battlefield." },
  { term: "Hold", explanation: "If you still control a battlefield when your Beginning phase reaches the holding check, you can score it, subject to the once-per-turn limit.", example: "Keep Sentry on the battlefield through their turn and you can pick up a holding point in your Beginning." },
  { term: "Priority", explanation: "When you have priority it’s your chance to act or pass, so check which cards you can legally play and pay for right now.", example: "Pass priority to give your opponent their chance. Once everyone passes, the newest waiting effect can resolve." },
  { term: "Chain", explanation: "Spells and abilities wait here until both players pass, then you resolve the newest one first. Resolve means follow its instructions now.", example: "If both of you play Discipline, you’ll resolve them one at a time with another response chance between them." },
  { term: "Counter", explanation: "Countering removes a waiting spell from the chain before its effect happens. Its costs stay spent, and you still have to choose a target the counterspell can affect.", example: "Play Defy while Rune Prison is waiting and you can stop the stun, but give your opponent their chance to respond to Defy itself." },
  { term: "Might", explanation: "This is a unit’s current fighting strength, so check the printed number and any effects changing it before you work out the damage.", example: "An extra 2 Might this turn might keep your unit alive through a fight it would otherwise lose." },
  { term: "Buff", explanation: "A Buff gives +1 Might and is a specific status a card can check or spend. Other effects can give Might without giving you a Buff.", example: "Discipline gives +2 this turn, so that extra Might on its own won’t pay the Buff cost for Monastery of Hirana." },
  { term: "Stun", explanation: "A stunned unit contributes no Might to combat damage this turn. It keeps its Might and readiness, and Stun on its own won’t stop it moving.", example: "A stunned defender on 4 Might still needs 4 damage to die, even though it deals none back. Stun ends in end-of-turn cleanup." },
  { term: "Recall", explanation: "Put the permanent back in its base. It doesn’t count as a move, so abilities that trigger on moving won’t trigger from the recall.", example: "If the unit was sideways, damaged or had a status, it still has those when it gets back to base unless a rule or effect changes them." },
  { term: "Banish", explanation: "Put the card into Banishment. It has its own space, separate from the trash, and banishing by itself doesn’t count as killing or discarding.", example: "A banished unit won’t trigger Deathknell just for being banished, though a card can specifically refer to Banishment." },
  { term: "Burn", explanation: "Take the stated number of cards from the top of the player’s main deck and put them in their trash.", example: "Burn 2 puts the top two cards in the trash. Their score and their units’ damage stay as they were." },
  { term: "Predict", explanation: "Look privately at the stated number of cards on top of your main deck, or one if there’s no number. Recycle any of them and put the rest back on top in whatever order you choose.", example: "With Predict 2 you can keep both on top in the order you want, recycle one or recycle both. The cards stay out of your hand and your opponent doesn’t see them." }
];

export const NEW_PLAYER_GLOSSARY: NewPlayerKeyword[] = [
  ...NEW_PLAYER_KEYWORD_SCENARIOS.map((scenario) => ({ term: scenario.keyword, explanation: scenario.definition ?? scenario.instruction, example: scenario.explanation })),
  ...FOUNDATION_GLOSSARY.filter((entry) => !NEW_PLAYER_KEYWORD_SCENARIOS.some((scenario) => scenario.keyword === entry.term)),
  ...NEW_PLAYER_TABLE_TERMS.filter(entry => !FOUNDATION_GLOSSARY.some(item => item.term.toLowerCase() === entry.term.toLowerCase()) && !NEW_PLAYER_KEYWORD_SCENARIOS.some(item => item.keyword.toLowerCase() === entry.term.toLowerCase())).map(({term, explanation, example}) => ({term, explanation, example}))
];
